-- public.path_pick_refusal(p_world uuid, p_uid uuid, p_pick text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.path_pick_refusal(p_world uuid, p_uid uuid, p_pick text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare k path_pick; p player; v_other text; v_at int; v_med double precision;
begin
  select * into k from path_pick where id = p_pick;
  if not found then return 'No such pick.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  if p.way is null then return 'Choose a path first (opens at meditation ' || choose_at()::int || ').'; end if;
  if k.path <> p.way then
    return 'Not your path: ' || coalesce((select name from path_def where id = k.path), k.path) || ' (yours: '
        || coalesce((select name from path_def where id = p.way), p.way) || ').';
  end if;
  if not path_moved(p.way) then
    return coalesce((select name from path_def where id = p.way), p.way) || ': still on steps, not path tiers.';
  end if;
  if exists (select 1 from path_taken where world_id = p_world and uid = p_uid and pick = p_pick) then
    return 'Already taken.';
  end if;
  select o.name into v_other from path_taken t join path_pick o on o.id = t.pick
   where t.world_id = p_world and t.uid = p_uid and o.path = k.path and o.tier = k.tier
   order by t.took limit 1;
  if v_other is not null then return 'Path tier already taken: ' || v_other || '.'; end if;
  v_at := (select at from path_tier where tier = k.tier);
  v_med := skill_of(p_world, p_uid, meditation_skill());
  if v_med < v_at then
    return 'Path tier opens at meditation ' || v_at || ' (have ' || floor(v_med)::int || ').';
  end if;
  return null;
end $function$
